package io.github.capozziv.digitalbanking.notification.bootstrap.web

import org.assertj.core.api.Assertions.assertThat
import org.junit.jupiter.api.Test
import org.springframework.boot.test.web.server.LocalServerPort
import tools.jackson.databind.JsonNode

/** The OpenAPI contract generated by springdoc documents the two operations of the notification API and their errors. */
class OpenApiIntegrationTest : NotificationWebIntegrationTest() {
    @LocalServerPort
    private var port: Int = 0

    private val docs: JsonNode by lazy {
        val response = ApiClient(port).get("/v3/api-docs")
        assertThat(response.status).describedAs(response.rawBody).isEqualTo(200)
        response.body!!
    }

    @Test
    fun `the contract has exactly the two operations of the spec`() {
        assertThat(operations().map { it.first }).containsExactlyInAnyOrder("GET /notifications", "POST /notifications/read")
    }

    @Test
    fun `list documents its parameters and the validation problem`() {
        val list = operation("GET /notifications")

        val parameters = list.get("parameters").associateBy { it.get("name").asString() }
        assertThat(parameters.getValue("customerId").get("required").asBoolean()).isTrue()
        assertThat(parameters.getValue("cursor").get("required").asBoolean()).isFalse()
        assertThat(
            list
                .get("responses")
                .get("400")
                .get("description")
                .asString(),
        ).contains("/problems/validation-error")
    }

    @Test
    fun `mark as read documents 404 notification-not-found and 400 validation-error`() {
        val responses = operation("POST /notifications/read").get("responses")

        assertThat(responses.get("200")).isNotNull()
        assertThat(responses.get("404").get("description").asString()).contains("/problems/notification-not-found")
        assertThat(responses.get("400").get("description").asString()).contains("/problems/validation-error")
    }

    @Test
    fun `every operation documents 500 internal-error as Problem Details`() {
        for ((name, operation) in operations()) {
            val internalError = operation.get("responses").get("500")
            assertThat(internalError).describedAs(name).isNotNull()
            assertThat(internalError.get("content").get("application/problem+json")).describedAs(name).isNotNull()
        }
    }

    @Test
    fun `the schemas carry the notification fields`() {
        val schemas = docs.get("components").get("schemas")

        assertThat(schemas.get("NotificationPageDTO").get("properties").propertyNames()).contains("items", "unreadCount", "nextCursor")
        assertThat(schemas.get("NotificationDTO").get("properties").propertyNames())
            .contains("id", "kind", "title", "body", "data", "createdAt", "readAt")
        assertThat(schemas.get("MarkNotificationsReadDTO").get("properties").propertyNames()).contains("customerId", "upTo")
    }

    private fun operations(): List<Pair<String, JsonNode>> {
        val paths = docs.get("paths")
        return paths.propertyNames().flatMap { path ->
            paths.get(path).propertyNames().map { method -> "${method.uppercase()} $path" to paths.get(path).get(method) }
        }
    }

    private fun operation(name: String): JsonNode = operations().single { it.first == name }.second
}
